"""Bind only a completed, independently audited P9b bank; does not fit or launch."""
import json,hashlib,subprocess,sys,sqlite3
from pathlib import Path
import pandas as pd,numpy as np
p=Path(__file__).parent;b=p.parent/'p9b';w=p/'worktree'
def rec(x):return {'path':str(x),'sha256':hashlib.sha256(x.read_bytes()).hexdigest()}
con=sqlite3.connect('file:/Users/adeliyaleleytner/.cache/cyp-inhibition/orx-store/orx.db?mode=ro',uri=True);run=con.execute('select status,commit_sha from runs where id=?',('f870d574-9ed7-4b77-b0c6-e42ec35509dd',)).fetchone();assert run==('done','8ab23c4d9513919e71dd50f6e25b0cbc75eb42df'),run
complete=json.load(open(b/'results/COMPLETE.json'));supervisor=json.load(open(b/'results/supervisor.json'));assert complete['status']=='complete' and complete['successful']==5655 and complete['failed']==0;assert supervisor['returncode']==0 and supervisor['elapsed_seconds']<=5400
subprocess.run([sys.executable,str(b/'audit_completed_coordinates.py')],check=True);audit=json.load(open(b/'COORDINATE_AUDIT.json'));assert audit['status']=='complete_pass' and audit['persisted_coordinate_rows']==5655 and not audit['flagged']
expected=pd.read_csv(p.parent/'p9a/next-stage/official5655-structures.csv');rows=pd.read_csv(b/'results/embedding-rows.csv');bank=np.load(b/'results/embeddings.npy');assert rows.Molecule_Name.tolist()==expected.Molecule_Name.tolist() and rows.SMILES.tolist()==expected.SMILES.tolist();assert bank.shape==(5655,256) and np.isfinite(bank).all();outcomes=[json.loads(x) for x in (b/'results/row-outcomes.jsonl').read_text().splitlines()];assert len(outcomes)==5655 and all(x['status']=='success' for x in outcomes) and [x['id'] for x in outcomes]==expected.Molecule_Name.tolist()
config=json.load(open(w/'p9_tabicl_config.json'))
for key,path in [('bank_complete',b/'results/COMPLETE.json'),('bank_rows',b/'results/embedding-rows.csv'),('bank_features',b/'results/embeddings.npy'),('bank_audit',b/'COORDINATE_AUDIT.json')]:config[key]=rec(path)
config['files']['bank_config']=rec(b/'worktree/p9b_config.json');config['bank_expected_worker_sha256']=rec(b/'worktree/night/p9b_bank.py')['sha256'];assert complete['source_sha256']==config['bank_expected_worker_sha256'] and complete['config_sha256']==config['files']['bank_config']['sha256'];config['bank_run']='f870d574-9ed7-4b77-b0c6-e42ec35509dd';config['bank_source_commit']=run[1];(w/'p9_tabicl_config.json').write_text(json.dumps(config,indent=2)+'\n');(p/'BANK_BINDING.json').write_text(json.dumps({'status':'verified_and_bound','run':config['bank_run'],'source':run[1],'rows':5655,'bank':config['bank_features'],'audit':config['bank_audit'],'source_sha256':rec(Path(__file__))['sha256'],'no_launch_or_fit':True},indent=2)+'\n');print('Completebankidentity,chemistry,runtime,source andhashpins verified; configbound. Commit before ORXlaunch.')
